alt(){const X=ALT.map(a=>{const d={...D,...a[2]};return{a,d,s:stats(d)}});return X.map(({a,d,s})=>`<div class="card"><small>OPTION ${a[0]}</small><h4>${a[1]}</h4><div style="display:flex;gap:4px;margin:6px 0">${['wall','floor','furn','ext'].map(k=>`<i title="${k}" style="width:26px;height:26px;border-radius:50%;background:${d[k]};border:1px solid #0003"></i>`).join('')}</div><p><b>${rng(s)}</b><br>${d.style} · ${d.mat} · ${s.n} rooms · living ${d.lw} m · kitchen ${d.kw} m wide</p><p>+ ${a[3]}<br>− ${a[4]}</p><button class="pri" style="padding:8px 14px" onclick="loadAlt('${a[0]}')">Load into 3D</button></div>`).join('')+`<div class="card"><h4>Side by side</h4><table style="width:100%;font-size:12px"><tr><th></th>${X.map(x=>'<th>'+x.a[0]+'</th>').join('')}</tr>${[['Cost',x=>rng(x.s)],['Area',x=>Math.round(x.s.ar)+' sq ft'],['Finish',x=>x.d.mat],['Window',x=>x.d.win+' m'],['Solar',x=>x.d.solar?'Yes':'No']].map(([n,f])=>`<tr><td>${n}</td>${X.map(x=>'<td>'+f(x)+'</td>').join('')}</tr>`).join('')}</table><small>Swatches show each palette; loading applies it to the real 3D model and history.</small></div>`},
