function ui2(){for(const e of[$('#ub'),$('#lsb')]){e.style.display=API_OK?'':'none';e.textContent=U?U.name:'Sign in'}svu()}
function svu(){const e=$('#sv');const t=!API_OK||!U?'':({saving:'Saving…',saved:'Saved to account',dirty:'Unsaved changes',failed:'Save failed. Retry'}[svS]||(PRJ?'':'Not saved to account'));e.textContent=t;e.style.display=t?'':'none'}
function markDirty(){if(!started||!U)return;dirty=true;chg++;svS='dirty';svu();clearTimeout(saveT);if(PRJ)saveT=setTimeout(()=>cloudSave(),2500)}
function guard(fn){if(dirty&&U)ask('You have unsaved changes. Discard them?',fn);else fn()}
function saveBtn(){if(API_OK&&U)cloudSave(true);else{save();if(API_OK)toast('Saved in this browser only. Sign in to save to your account.')}}
async function cloudSave(manual){if(!API_OK)return;if(!U){if(manual)authModal();return}if(saving){dirty=true;return}clearTimeout(saveT);saving=true;svS='saving';svu();const c0=chg,th=thumb(),body={name:(D.name||'My Villa').slice(0,80),state:stateOut(),design:D.custom||null,...(th?{thumbnail:th}:{})};
const r=PRJ?await api('/projects/'+PRJ.id,{method:'PUT',body:{...body,rev:PRJ.rev}}):await api('/projects',{method:'POST',body});saving=false;
if(r.ok){PRJ={id:r.d.project.id,rev:r.d.project.rev};if(chg==c0){dirty=false;svS='saved'}else{svS='dirty';saveT=setTimeout(()=>cloudSave(),1000)}svu();if(manual)toast('Saved to your account');if(tab=='cloud')tabs();return}
svS='failed';svu();if(r.status==409)ask('This project was changed elsewhere (another tab or device). Overwrite the server copy with this version?',async()=>{const g=await api('/projects/'+PRJ.id);if(g.ok){PRJ.rev=g.d.project.rev;cloudSave(true)}});else if(r.status==401){U=null;PRJ=null;ui2();authModal()}else toast(r.d.message||'Save failed')}
function authModal(mode='login'){const rg=mode=='register';mo(`<h3>${rg?'Create your account':'Sign in'}</h3><form onsubmit="return authGo(event,'${mode}')">${rg?'<label for="an">Name</label><input id="an" autocomplete="name" required maxlength="60">':''}<label for="ae">Email</label><input id="ae" type="email" autocomplete="email" required><label for="ap2">Password${rg?' (8+ characters)':''}</label><input id="ap2" type="password" autocomplete="${rg?'new':'current'}-password" required minlength="${rg?8:1}"><p id="aerr" role="alert" style="color:#b3412a;min-height:20px"></p><button class="pri" type="submit">${rg?'Create account':'Sign in'}</button> <button type="button" onclick="authModal('${rg?'login':'register'}')">${rg?'I have an account':'Create account'}</button></form>`)}
async function authGo(e,mode){e.preventDefault();const b={email:$('#ae').value,password:$('#ap2').value};if(mode=='register')b.name=$('#an').value;$('#aerr').textContent='Please wait…';const r=await api('/auth/'+mode,{method:'POST',body:b});if(!r.ok){$('#aerr').textContent=(r.d.message||'Failed')+(r.d.details?': '+r.d.details.map(x=>x.message).join(', '):'');return false}U=r.d.user;mc();ui2();tabs();toast('Signed in as '+U.name);if(started&&!PRJ)markDirty();return false}
function acct(){if(!U)return authModal();mo(`<p><b>${esc(U.name)}</b><br><small>${esc(U.email)}</small></p><div class="bt"><button onclick="mc();T('cloud')">My Projects</button><button onclick="mc();logout()">Sign out</button></div>`)}
function logout(){guard(async()=>{await api('/auth/logout',{method:'POST'});U=null;PRJ=null;dirty=false;svS='';ui2();tabs();toast('Signed out')})}
async function loadCloud(){const q=($('#cq')||{}).value||'',r=await api('/projects?q='+encodeURIComponent(q.slice(0,60))),el=$('#cl');if(!el)return;if(!r.ok){el.innerHTML='<div class="card"><small>'+esc(r.d.message||'Could not load projects')+'</small> <button onclick="loadCloud()">Retry</button></div>';return}CL=r.d.projects;el.innerHTML=CL.length?CL.map(p=>`<div class="card">${p.thumbnail?`<img class="th" alt="Preview of ${esc(p.name)}" src="${esc(p.thumbnail)}">`:''}<h4>${esc(p.name)}</h4><small>${esc(p.style||'Custom')} · ${p.floors} floor(s) · updated ${new Date(p.updatedAt).toLocaleDateString()}</small><div class="bt" style="margin-top:8px"><button onclick="openCloud('${p.id}')">Open</button><button onclick="renC('${p.id}')">Rename</button><button onclick="dupC('${p.id}')">Duplicate</button><button onclick="delC('${p.id}')">Delete</button></div></div>`).join(''):'<div class="card"><small>No saved designs yet. Press Save to add the current design to your account.</small></div>'}
function openCloud(id){guard(async()=>{const r=await api('/projects/'+id);if(!r.ok)return toast(r.d.message||'Could not open');const p=r.d.project;D={...BASE,...p.state,name:p.name};if(p.design)applySpecTo(D,p.design);else delete D.custom;PRJ={id:p.id,rev:p.rev};start();dirty=false;chg=0;svS='saved';svu();toast('Opened '+p.name)})}
function renC(id){const p=CL.find(x=>x.id==id);if(!p)return;window._cid=id;mo(`<label for="rn2">Project name</label><input id="rn2" maxlength="80" value="${esc(p.name)}"><button class="pri" style="margin-top:10px" onclick="renGo()">Rename</button>`)}
async function renGo(){const p=CL.find(x=>x.id==_cid),n=$('#rn2').value.trim();if(!p||!n)return;const g=await api('/projects/'+p.id),r=g.ok?await api('/projects/'+p.id,{method:'PATCH',body:{rev:g.d.project.rev,name:n}}):g;mc();if(!r.ok)return toast(r.d.message||'Rename failed');if(PRJ&&PRJ.id==p.id){PRJ.rev=r.d.project.rev;D.name=n}toast('Renamed');loadCloud()}
async function dupC(id){const r=await api('/projects/'+id+'/duplicate',{method:'POST'});toast(r.ok?'Duplicated':r.d.message||'Failed');loadCloud()}
function delC(id){ask('Delete this project from your account? This cannot be undone.',async()=>{const r=await api('/projects/'+id,{method:'DELETE'});if(r.ok&&PRJ&&PRJ.id==id){PRJ=null;markDirty()}toast(r.ok?'Deleted':r.d.message||'Failed');loadCloud()})}
PN.cloud=()=>!API_OK?'<div class="card"><small>Accounts need the ArchNova server (npm start). This page is running without it, so designs are saved in this browser only.</small></div>':!U?'<div class="card"><h4>Sign in</h4><p>Save designs to your account and reopen them on any device.</p><button class="pri" onclick="authModal()">Sign in</button> <button onclick="authModal(\'register\')">Create account</button></div>':(setTimeout(loadCloud,0),'<div class="row"><input id="cq" placeholder="Search my projects" aria-label="Search my projects" oninput="clearTimeout(window._cqt);window._cqt=setTimeout(loadCloud,300)"></div><div id="cl"><div class="card sk"></div><div class="card sk"></div></div>');
// ================= AI design generation / modification =================
const AIP='Design a modern two-storey Indian family home on a 30 by 40 foot plot with three bedrooms, an open kitchen, a living room, two bathrooms, a balcony and plenty of natural light, medium budget.';
PN.aid=()=>{if(!API_OK)return'<div class="card"><small>AI design needs the ArchNova server. Run <b>npm start</b> with your AI key configured (see README).</small></div>';if(!U)return'<div class="card"><h4>Sign in to use AI design</h4><p>AI requests run on the server and need an account.</p><button class="pri" onclick="authModal()">Sign in</button></div>';
const P=AI.pending,busy=AI.busy;return`<label for="apr">Describe your house</label><textarea id="apr" rows="4" maxlength="1500">${esc(AI.last||AIP)}</textarea><div class="bt" style="margin:8px 0"><button class="pri" ${busy?'disabled':''} onclick="aiGen()">Generate Design</button>${AI.last?`<button ${busy?'disabled':''} onclick="aiGen()">Regenerate</button>`:''}</div>
<label for="amo">Modify this design</label><textarea id="amo" rows="2" maxlength="500" placeholder="e.g. Make the living room larger"></textarea><div class="bt" style="margin:8px 0"><button ${busy||!D.custom?'disabled':''} onclick="aiMod()">Modify This Design</button></div>${D.custom?'':'<small>Modify works on AI-generated layouts. Generate one first; the built-in template house is not sent to the AI.</small>'}
${busy?'<div class="card sk"></div><small role="status">Working… this can take up to a minute. Your current design is unchanged.</small>':''}${AI.err?`<div class="card" role="alert"><b>Could not complete</b><p>${esc(AI.err)}</p><small>Your current design was not changed.</small></div>`:''}
${P?aiCard(P):''}${AI.prev?'<div class="bt" style="margin-top:8px"><button onclick="aiRevert()">Revert Changes</button></div>':''}<div class="bt" style="margin-top:8px"><button onclick="saveBtn()">Save Design</button><button onclick="T(\'exp\')">Export Design</button></div><small>AI layouts are concept designs. They are validated for geometry only, not for structure or building codes.</small>`};
function aiCard(P){const d=P.design,s=stats({...D,custom:d,floors:d.floors});return`<div class="card" style="outline:2px solid var(--a)"><small>PROPOSED${P.diff?' CHANGE':' DESIGN'} (not applied yet)</small><h4>${esc(d.style)} · ${d.floors} floor(s) · ${d.rooms.length} rooms</h4><p>Plot ${d.plot.width.toFixed(1)} × ${d.plot.length.toFixed(1)} m · ${Math.round(s.ar)} sq ft<br>Estimate ${rng(s)} <small>(planning estimate)</small></p>${P.diff?'<p>'+(P.diff.length?P.diff.map(c=>'• '+esc(c.room||c.field)+' '+esc(c.change||(c.from!==undefined?c.from+' → '+c.to:'changed'))).join('<br>'):'No layout changes detected.')+'</p>':''}${P.warnings&&P.warnings.length?'<p><small>Warnings: '+P.warnings.map(esc).join('; ')+'</small></p>':''}${d.explanation?'<p><small>AI explanation: '+esc(d.explanation)+'</small></p>':''}<div class="bt"><button class="pri" onclick="aiApply()">Apply Changes</button><button onclick="AI.pending=null;tabs()">Discard</button></div></div>`}
async function aiRun(path,body,diffOK){AI.busy=true;AI.err='';tabs();const r=await api(path,{method:'POST',body});AI.busy=false;if(!r.ok){AI.err=(r.d.message||'Request failed')+(r.d.details?': '+r.d.details.slice(0,3).map(x=>typeof x=='string'?x:x.message).join('; '):'');tabs();return}const e=specOk(r.d.design);if(e.length){AI.err='The design failed validation in the browser: '+e.slice(0,3).join('; ');tabs();return}AI.pending={design:r.d.design,warnings:r.d.warnings,diff:diffOK?r.d.diff:null};tabs()}
function aiGen(){const p=($('#apr')||{}).value||AI.last||'';if(p.trim().length<10)return toast('Describe the house in at least 10 characters');AI.last=p.trim();aiRun('/ai/generate-design',{prompt:AI.last},false)}
function aiMod(){const i=($('#amo').value||'').trim();if(i.length<3)return toast('Describe the change first');if(!D.custom)return;aiRun('/ai/modify-design',{design:D.custom,instruction:i},true)}
function aiApply(){const P=AI.pending;if(!P)return;const e=specOk(P.design);if(e.length)return toast('Cannot apply: '+e[0]);AI.prev=JSON.parse(JSON.stringify(D));applySpecTo(D,P.design);if(ok){const m=MP[D.mat];if(m){mats.floor.roughness=m[1];mats.floor.metalness=m[2]}}AI.pending=null;rebuild('AI design applied');ext();tabs();toast('AI design applied. Use Revert Changes to go back.')}
function aiRevert(){if(!AI.prev)return;D={...BASE,...AI.prev};AI.prev=null;rebuild('AI change reverted');ext();tabs();toast('Reverted')}
(async()=>{try{const h=await fetch('/api/health');API_OK=h.ok&&(await h.json()).ok===true}catch(e){API_OK=false}if(API_OK){const m=await api('/auth/me');if(m.ok)U=m.d.user}ui2()})();
addEventListener('beforeunload',e=>{if(dirty&&U){e.preventDefault();e.returnValue=''}});
// ================= Exports and import (Phase 8) =================
const fnm=ext=>(D.name||'archnova').replace(/[^\w.-]+/g,'_').slice(0,50)+'.'+ext;
function dl(data,name,type){const b=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function planOut(){const hz=d=>d[4]!==undefined?d[4]:[0,5,9].includes(d[2]),g=D.floors>1?(D.custom?stairGeo():{x:.4,z:5.6,w:1.2,d:3}):null;
return{name:(D.name||'My Villa').slice(0,80),style:(D.style||'').slice(0,40),units:'m',plot:{width:PW(),length:PL()},floors:D.floors,rooms:R.map(r=>({id:r.id,name:r.n,type:r.type||(r.open?'balcony':r.id=='landing'?'landing':'room'),floor:r.f,x:r.x,z:r.z,w:r.w,d:r.d,furniture:(r.fu||[]).map(f=>({type:f[0],fx:f[1],fz:f[2],rot:f[3]||0}))})),doors:DR.map(d=>({floor:d[0],x:d[1],z:d[2],width:d[3]||1,hz:!!hz(d)})),windows:[0,1].flatMap(f=>(WN[f]||[]).map(([h,t,c,w])=>({floor:f,hor:!!h,t,c,width:w||D.win}))),...(g?{stairs:{x:g.x,z:g.z,w:g.w,d:g.d}}:{}),materials:{wall:D.wall,floor:D.floor,furniture:D.furn,exterior:D.ext,floorMaterial:D.mat},budgetTier:['basic','standard','premium'][D.q??1]}}
const envOut=()=>({format:'archnova-project',schemaVersion:1,exportedAt:new Date().toISOString(),app:'ArchNova',project:{name:(D.name||'My Villa').slice(0,80),description:'',state:stateOut(),design:D.custom||null}});
function exJson(){dl(JSON.stringify(envOut(),null,2),fnm('archnova.json'),'application/json');toast('Project JSON downloaded')}
async function exSrv(path,ext,floor){if(!API_OK)return toast('This export needs the ArchNova server');let r;try{r=await fetch('/api/export/'+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'archnova'},body:JSON.stringify({plan:planOut(),...(floor!==undefined?{floor}:{})})})}catch(e){return toast('Cannot reach the server')}if(!r.ok){let m='Export failed';try{m=(await r.json()).message||m}catch(e){}return toast(m)}const n=fnm(ext);dl(await r.blob(),n);toast('Downloaded '+n)}
function exPng(){if(!ok||vm!='3d')return toast('Switch to the 3D view first');rd.render(scene,cam);$('#cv').toBlob(b=>b?dl(b,fnm('png')):toast('Could not capture the image'),'image/png')}
function loadScript(u){return new Promise((res,rej)=>{if(document.querySelector('script[src="'+u+'"]'))return res();const s=document.createElement('script');s.src=u;s.onload=res;s.onerror=()=>rej(new Error('Could not load the 3D exporter library (internet needed)'));document.head.appendChild(s)})}
async function exGlb(){if(!ok)return toast('3D is not available on this device');try{await loadScript('https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/exporters/GLTFExporter.js')}catch(e){return toast(e.message)}const vis=[G[1].visible,ROOF.visible],back=()=>{G[1].visible=vis[0];ROOF.visible=vis[1]};G[1].visible=ROOF.visible=true;toast('Preparing 3D model…');try{new THREE.GLTFExporter().parse(root,res=>{back();dl(new Blob([res],{type:'model/gltf-binary'}),fnm('glb'));toast('3D model (GLB) downloaded')},{binary:true,onlyVisible:true})}catch(e){back();toast('3D model export failed: '+e.message)}}
async function exBackup(){if(!U)return toast('Sign in to back up your projects');const r=await fetch('/api/projects/backup',{credentials:'same-origin'});if(!r.ok)return toast('Backup failed');dl(await r.blob(),'archnova-backup.json');toast('Backup downloaded')}
const importErr=d=>mo('<h3>Import failed</h3><p>'+esc(d.message||'Invalid file')+'</p>'+(d.details?'<ul>'+d.details.slice(0,8).map(x=>'<li>'+esc(typeof x=='string'?x:x.path+': '+x.message)+'</li>').join('')+'</ul>':''));
async function importFile(inp){const f=inp.files[0];inp.value='';if(!f)return;if(f.size>1e6)return toast('File is too large (max 1 MB)');let j;try{j=JSON.parse(await f.text())}catch(e){return toast('That file is not valid JSON')}let out;
if(API_OK){const r=await api('/export/validate-import',{method:'POST',body:j});if(!r.ok)return importErr(r.d);out=r.d}else{const p=j&&j.project;if(!j||j.format!='archnova-project'||j.schemaVersion!==1||!p||!p.state)return toast('Not a valid ArchNova project file (checked offline)');const e=p.design?specOk(p.design):[];if(e.length)return importErr({message:'Invalid design',details:e});out={kind:'project',projects:[p]}}
if(out.kind=='backup'){if(!U)return toast('Sign in to restore a backup');return ask(`Restore ${out.projects.length} projects into your account? Existing projects are kept.`,async()=>{const r=await api('/projects/restore',{method:'POST',body:j});toast(r.ok?`Restored ${r.d.created} projects`:r.d.message||'Restore failed');if(tab=='cloud')loadCloud()})}
const p=out.projects[0],st={};SK.forEach(k=>{if(p.state[k]!==undefined)st[k]=p.state[k]});ask(`Replace the current design with "${p.name}"? Unsaved changes to the current design will be lost.`,()=>{D={...BASE,...st,name:p.name};if(p.design)applySpecTo(D,p.design);else delete D.custom;PRJ=null;start();toast('Imported "'+p.name+'"')})}
PN.exp=()=>{const dis=API_OK?'':' disabled title="Needs the ArchNova server"';return`<div class="card"><h4>Design files</h4><div class="bt"><button onclick="exJson()">Project JSON</button><button onclick="exSrv('floorplan.svg','ground-floor.svg',0)"${dis}>Plan SVG${D.floors>1?' (ground)':''}</button>${D.floors>1?`<button onclick="exSrv('floorplan.svg','first-floor.svg',1)"${dis}>Plan SVG (first)</button>`:''}<button onclick="exSrv('floorplan.pdf','floorplan.pdf')"${dis}>Floor plan PDF</button><button onclick="exSrv('summary.pdf','summary.pdf')"${dis}>Summary PDF</button><button onclick="exPng()">3D preview PNG</button><button onclick="exGlb()">3D model GLB</button></div><small>The PDFs include every floor and a room schedule. JSON is editable project data, not a 3D model; GLB holds the actual 3D geometry.</small></div><div class="card"><h4>Backup and import</h4><div class="bt"><button onclick="exBackup()"${U?'':' disabled title="Sign in first"'}>Backup all my projects</button><button onclick="$('#imf').click()">Import JSON…</button></div><input id="imf" type="file" accept=".json,application/json" hidden onchange="importFile(this)"><small>Imports are validated, and you confirm before the current design is replaced. Max 1 MB.</small></div><div class="card"><h4>Quick copy</h4><div class="bt"><button onclick="cj()">Copy JSON</button><button onclick="csvg()">Copy plan SVG</button><button onclick="cap()">Preview image</button><button onclick="prt()">Print report</button><button onclick="summary()">Copy summary</button></div></div>`};
heroOn();ui();
